namespace ShipmentTracker.Client.Models;

public enum ShipmentStatus
{
    Pending,
    PickedUp,
    InTransit,
    OutForDelivery,
    Delivered,
    Cancelled
}

public class Shipment
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
    public DateTime CreatedAt { get; set; }
    public DateTime? EstimatedDelivery { get; set; }
    public string CustomerEmail { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Client.Services;

public interface IShipmentService
{
    Task<List<Shipment>> GetAllShipmentsAsync();
    Task<Shipment?> GetByTrackingNumberAsync(string trackingNumber);
    Task<List<Shipment>> GetShipmentsForCustomerAsync(string email);
    Task UpdateStatusAsync(int id, ShipmentStatus status);
}

using System.Net.Http.Json;
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Client.Services;

public class ClientShipmentService(HttpClient http) : IShipmentService
{
    public async Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return await http.GetFromJsonAsync<List<Shipment>>("api/shipments") ?? [];
    }

    public async Task<Shipment?> GetByTrackingNumberAsync(string trackingNumber)
    {
        return await http.GetFromJsonAsync<Shipment?>($"api/shipments/track/{trackingNumber}");
    }

    public async Task<List<Shipment>> GetShipmentsForCustomerAsync(string email)
    {
        return await http.GetFromJsonAsync<List<Shipment>>($"api/shipments/customer/{Uri.EscapeDataString(email)}") ?? [];
    }

    public async Task UpdateStatusAsync(int id, ShipmentStatus status)
    {
        await http.PutAsJsonAsync($"api/shipments/{id}/status", status);
    }
}

using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Services;

public class ServerShipmentService : IShipmentService
{
    private static readonly List<Shipment> Shipments = new()
    {
        new() { Id = 1, TrackingNumber = "TRK-001-2026", Origin = "New York, US", Destination = "London, UK", Status = ShipmentStatus.InTransit, CreatedAt = DateTime.UtcNow.AddDays(-3), EstimatedDelivery = DateTime.UtcNow.AddDays(2), CustomerEmail = "alice@example.com", Description = "Electronics - 2 boxes" },
        new() { Id = 2, TrackingNumber = "TRK-002-2026", Origin = "Shanghai, CN", Destination = "Los Angeles, US", Status = ShipmentStatus.PickedUp, CreatedAt = DateTime.UtcNow.AddDays(-1), EstimatedDelivery = DateTime.UtcNow.AddDays(7), CustomerEmail = "bob@example.com", Description = "Furniture - 1 pallet" },
        new() { Id = 3, TrackingNumber = "TRK-003-2026", Origin = "Berlin, DE", Destination = "Tokyo, JP", Status = ShipmentStatus.OutForDelivery, CreatedAt = DateTime.UtcNow.AddDays(-5), EstimatedDelivery = DateTime.UtcNow, CustomerEmail = "alice@example.com", Description = "Auto parts - 3 crates" },
        new() { Id = 4, TrackingNumber = "TRK-004-2026", Origin = "Sydney, AU", Destination = "Mumbai, IN", Status = ShipmentStatus.Pending, CreatedAt = DateTime.UtcNow, EstimatedDelivery = DateTime.UtcNow.AddDays(10), CustomerEmail = "charlie@example.com", Description = "Textiles - 5 boxes" },
        new() { Id = 5, TrackingNumber = "TRK-005-2026", Origin = "São Paulo, BR", Destination = "Paris, FR", Status = ShipmentStatus.Delivered, CreatedAt = DateTime.UtcNow.AddDays(-10), EstimatedDelivery = DateTime.UtcNow.AddDays(-2), CustomerEmail = "bob@example.com", Description = "Food products - refrigerated" },
    };

    private static readonly Lock Lock = new();

    public Task<List<Shipment>> GetAllShipmentsAsync()
    {
        lock (Lock)
        {
            return Task.FromResult(Shipments.ToList());
        }
    }

    public Task<Shipment?> GetByTrackingNumberAsync(string trackingNumber)
    {
        lock (Lock)
        {
            return Task.FromResult(Shipments.FirstOrDefault(s =>
                s.TrackingNumber.Equals(trackingNumber, StringComparison.OrdinalIgnoreCase)));
        }
    }

    public Task<List<Shipment>> GetShipmentsForCustomerAsync(string email)
    {
        lock (Lock)
        {
            return Task.FromResult(Shipments.Where(s =>
                s.CustomerEmail.Equals(email, StringComparison.OrdinalIgnoreCase)).ToList());
        }
    }

    public Task UpdateStatusAsync(int id, ShipmentStatus status)
    {
        lock (Lock)
        {
            var shipment = Shipments.FirstOrDefault(s => s.Id == id);
            if (shipment is not null)
            {
                shipment.Status = status;
            }
        }
        return Task.CompletedTask;
    }
}

